scientific_definitions.src/evaluation.py:
"""Comprehensive evaluation metrics for benchmark experiments."""

from __future__ import annotations

import warnings
import numpy as np
import pandas as pd
from sklearn.metrics import (
    accuracy_score,
    balanced_accuracy_score,
    brier_score_loss,
    f1_score,
    log_loss,
    matthews_corrcoef,
    precision_score,
    recall_score,
    roc_auc_score,
    average_precision_score,
)

METRIC_SEMANTICS_VERSION = "encoded_class_probability_metrics_v2"
METRIC_RANGES = {name: (0.0, 1.0) for name in ("accuracy", "balanced_accuracy", "precision", "recall", "f1", "f1_macro", "roc_auc", "pr_auc", "brier_score")}
METRIC_RANGES.update({"mcc": (-1.0, 1.0), "log_loss": (0.0, np.inf)})


class MetricInputError(ValueError):
    """An input violates the declared target/probability coordinate contract."""


def compute_classification_metrics(
    y_true: np.ndarray,
    y_pred: np.ndarray,
    y_proba: np.ndarray,
    classes: np.ndarray | None = None,
    *,
    probability_classes: np.ndarray | None = None,
) -> dict:
    """
    Compute 10 classification metrics for the benchmark.

    Supports both Binary and Multiclass tasks automatically.
    """
    y_true = np.asarray(y_true).reshape(-1)
    y_pred = np.asarray(y_pred).reshape(-1)
    declared = np.asarray(classes if classes is not None else np.unique(y_true))
    if declared.ndim != 1 or len(set(declared.tolist())) != len(declared):
        raise MetricInputError("class coordinates must be unique and one-dimensional")
    if len(y_true) != len(y_pred):
        raise MetricInputError("target and prediction lengths differ")
    allowed = set(declared.tolist())
    if not set(y_true.tolist()).issubset(allowed) or not set(y_pred.tolist()).issubset(allowed):
        raise MetricInputError("target/prediction class is absent from declared class coordinates")
    # sklearn log_loss orders label coordinates; align to that order explicitly.
    labels = np.unique(declared)
    binary = len(labels) == 2
    names = list(METRIC_RANGES)
    metrics = {name: np.nan for name in names}
    statuses = {name: "undefined_empty_target" for name in names}
    metrics.update({"metric_semantics_version": METRIC_SEMANTICS_VERSION,
        "metric_status": statuses, "f1_averaging": "binary" if binary else "macro",
        "brier_normalization": "positive_class_mean_squared_error" if binary else "mean_over_samples_and_declared_classes"})
    if not len(y_true):
        return metrics
    metrics.update(accuracy=float(accuracy_score(y_true, y_pred)),
        balanced_accuracy=float(balanced_accuracy_score(y_true, y_pred)),
        mcc=float(matthews_corrcoef(y_true, y_pred)))
    kwargs = {"average": "binary", "pos_label": labels[1]} if binary else {"average": "macro", "labels": labels}
    metrics["precision"] = float(precision_score(y_true,y_pred,zero_division=0,**kwargs))
    metrics["recall"] = float(recall_score(y_true,y_pred,zero_division=0,**kwargs))
    metrics["f1"] = float(f1_score(y_true,y_pred,zero_division=0,**kwargs))
    metrics["f1_macro"] = float(f1_score(y_true,y_pred,average="macro",labels=labels,zero_division=0))
    for name in ("accuracy","balanced_accuracy","mcc","precision","recall","f1","f1_macro"):
        statuses[name] = "complete"
    for name in ("roc_auc","pr_auc","log_loss","brier_score"):
        statuses[name] = "undefined_no_probabilities" if y_proba is None else "undefined_single_declared_class"
    if y_proba is None:
        return metrics
    probabilities = np.asarray(y_proba)
    columns = np.asarray(probability_classes if probability_classes is not None else declared)
    if probabilities.ndim != 2 or probabilities.shape != (len(y_true), len(columns)):
        raise MetricInputError("probability dimensions do not match rows and class columns")
    if columns.ndim != 1 or len(set(columns.tolist())) != len(columns) or not set(columns.tolist()).issubset(allowed):
        raise MetricInputError("probability class coordinates are incompatible")
    if not np.isfinite(probabilities).all() or np.any(probabilities < 0) or np.any(probabilities > 1):
        raise MetricInputError("probabilities must be finite and within [0,1]")
    if not np.allclose(probabilities.sum(axis=1), 1.0, rtol=0, atol=1e-7):
        raise MetricInputError("probability rows must sum to one")
    aligned = np.zeros((len(y_true),len(labels)), dtype=probabilities.dtype)
    positions = {label: i for i,label in enumerate(labels.tolist())}
    for i,label in enumerate(columns.tolist()):
        aligned[:,positions[label]] = probabilities[:,i]
    if len(labels) < 2:
        return metrics
    metrics["log_loss"] = float(log_loss(y_true, aligned, labels=labels))
    if binary:
        metrics["brier_score"] = float(brier_score_loss(y_true == labels[1], aligned[:,1]))
    else:
        metrics["brier_score"] = float(np.mean([brier_score_loss(y_true == label, aligned[:,i]) for i,label in enumerate(labels)]))
    statuses["log_loss"] = statuses["brier_score"] = "complete"
    if len(np.unique(y_true)) != len(labels):
        statuses["roc_auc"] = statuses["pr_auc"] = "undefined_missing_held_out_class"
        return metrics
    if binary:
        metrics["roc_auc"] = float(roc_auc_score(y_true == labels[1],aligned[:,1]))
        metrics["pr_auc"] = float(average_precision_score(y_true == labels[1],aligned[:,1]))
    else:
        metrics["roc_auc"] = float(roc_auc_score(y_true,aligned,labels=labels,multi_class="ovr",average="macro"))
        metrics["pr_auc"] = float(np.mean([average_precision_score(y_true == label,aligned[:,i]) for i,label in enumerate(labels)]))
    statuses["roc_auc"] = statuses["pr_auc"] = "complete"
    return metrics

from scipy.stats import wasserstein_distance, ks_2samp

DISTRIBUTION_SEMANTICS_VERSION='frozen_mapping_training_corruption_distance_v2'

def compute_distribution_distance(
    x_clean: pd.DataFrame,
    x_shifted: pd.DataFrame,
    max_samples: int = 5000,
    random_state: int = 42,
) -> dict[str, float]:
    """Compare identical numeric coordinates under one frozen fitted mapping.

    Callers declare training corruption or held-out input scope. Independently
    selected/generated coordinate systems are unsupported.
    """
    status={'distribution_semantics_version':DISTRIBUTION_SEMANTICS_VERSION}
    if x_clean.empty or x_shifted.empty:
        return {**status,'distance_status':'unsupported_empty_inputs','wasserstein': None, 'ks_stat': None}
    if list(x_clean.columns) != list(x_shifted.columns):
        return {**status,'distance_status':'unsupported_coordinate_mismatch','wasserstein':None,'ks_stat':None}

    # Sample rows to keep compute feasible
    if len(x_clean) > max_samples:
        x_clean = x_clean.sample(n=max_samples, random_state=random_state)
    if len(x_shifted) > max_samples:
        x_shifted = x_shifted.sample(n=max_samples, random_state=random_state)

    # Ensure we only compare common numeric columns
    cols = [c for c in x_clean.columns if c in x_shifted.columns and pd.api.types.is_numeric_dtype(x_clean[c])]
    if not cols:
        return {**status,'distance_status':'unsupported_no_numeric_coordinates','wasserstein':None,'ks_stat':None}

    w_dists = []
    ks_dists = []
    for c in cols:
        # Drop NaNs for stability
        c_clean = x_clean[c].dropna().values
        c_shifted = x_shifted[c].dropna().values
        if len(c_clean) > 0 and len(c_shifted) > 0:
            try:
                w_dists.append(wasserstein_distance(c_clean, c_shifted))
                ks_dists.append(ks_2samp(c_clean, c_shifted).statistic)
            except Exception:
                pass

    return {
        **status,'distance_status':'complete' if len(w_dists) == len(cols) else 'incomplete_numeric_coordinates',
        'wasserstein': float(np.mean(w_dists)) if w_dists else np.nan,
        'ks_stat': float(np.mean(ks_dists)) if ks_dists else np.nan,
    }

def compute_jaccard_similarity(list_a: list[str], list_b: list[str]) -> float:
    """Compute Jaccard similarity between two lists of feature names."""
    set_a = set(list_a)
    set_b = set(list_b)
    if not set_a and not set_b:
        return 1.0
    return float(len(set_a.intersection(set_b)) / len(set_a.union(set_b)))

scientific_definitions.src/model.py:
"""Model factory for the 10 benchmark models.

All sklearn models use n_jobs=1 because we parallelize at the task level
(multiprocessing Pool). Setting n_jobs>1 here would cause thread thrashing.

GPU models (XGBoost, CatBoost) are configured to use CUDA automatically.
"""

from __future__ import annotations

from typing import Any

from sklearn.base import BaseEstimator
from sklearn.ensemble import ExtraTreesClassifier, RandomForestClassifier
from sklearn.linear_model import LogisticRegression
from sklearn.naive_bayes import GaussianNB
from sklearn.neighbors import KNeighborsClassifier
from sklearn.neural_network import MLPClassifier
from sklearn.svm import SVC


def build_model(
    model_type: str,
    random_state: int = 42,
    use_gpu: bool = True,
) -> BaseEstimator:
    """
    Build one of the 10 benchmark models with sensible defaults.

    All models use n_jobs=1 to prevent CPU thread thrashing when used
    inside a multiprocessing Pool. GPU models (XGBoost, CatBoost) are
    configured to use CUDA when use_gpu=True.
    """
    normalized = model_type.strip().lower()

    if normalized == "logistic_regression":
        return LogisticRegression(
            random_state=random_state,
            max_iter=1000,
            n_jobs=1,
        )

    elif normalized == "random_forest":
        return RandomForestClassifier(
            n_estimators=100,
            random_state=random_state,
            n_jobs=1,
        )

    elif normalized == "extra_trees":
        return ExtraTreesClassifier(
            n_estimators=100,
            random_state=random_state,
            n_jobs=1,
        )

    elif normalized == "xgboost":
        from xgboost import XGBClassifier
        params = dict(
            n_estimators=100,
            random_state=random_state,
            n_jobs=1,
            eval_metric="logloss",
            tree_method="hist",
            verbosity=0,
        )
        if use_gpu:
            params["device"] = "cuda"
        return XGBClassifier(**params)

    elif normalized == "lightgbm":
        from lightgbm import LGBMClassifier
        return LGBMClassifier(
            n_estimators=100,
            random_state=random_state,
            n_jobs=1,
            verbose=-1,
        )

    elif normalized == "catboost":
        from catboost import CatBoostClassifier
        params = dict(
            iterations=100,
            random_state=random_state,
            thread_count=1,
            verbose=False,
            allow_writing_files=False,
        )
        if use_gpu:
            params["task_type"] = "GPU"
            params["devices"] = "0"
        return CatBoostClassifier(**params)

    elif normalized == "linear_svm":
        from sklearn.svm import LinearSVC
        from sklearn.calibration import CalibratedClassifierCV
        base_svm = LinearSVC(
            random_state=random_state,
            max_iter=1000,
            dual="auto",
        )
        return CalibratedClassifierCV(base_svm, cv=3)

    elif normalized == "knn":
        return KNeighborsClassifier(
            n_neighbors=5,
            n_jobs=1,
        )

    elif normalized == "gaussian_nb":
        return GaussianNB()

    elif normalized == "mlp":
        return MLPClassifier(
            hidden_layer_sizes=(100,),
            max_iter=500,
            random_state=random_state,
            early_stopping=True,
        )

    else:
        raise ValueError(f"Unknown model type: {model_type}")

scientific_definitions.src/operator_registry.py:
"""Versioned arithmetic operators and stable expression identities.

The benchmark only uses the operators declared here.  Expression trees are
represented as nested tuples so candidate generation, evaluation, derivative
calculation, and persisted histories share one executable definition.
"""

from __future__ import annotations

import hashlib
import json
from dataclasses import dataclass
from typing import Any

import numpy as np


OPERATOR_REGISTRY_VERSION = "arithmetic_operator_registry_v1"
OPERATOR_SEMANTICS_VERSION = "safe_division_1e-12_clip_1e12_v1"
SAFE_DIVISION_EPSILON = 1e-12
FINITE_CLIP = 1e12


@dataclass(frozen=True)
class OperatorSpec:
    name: str
    symbol: str
    commutative: bool


OPERATOR_REGISTRY: dict[str, OperatorSpec] = {
    "add_numeric": OperatorSpec("add_numeric", "+", True),
    "subtract_numeric": OperatorSpec("subtract_numeric", "-", False),
    "multiply_numeric": OperatorSpec("multiply_numeric", "*", True),
    "divide_numeric": OperatorSpec("divide_numeric", "/", False),
}

OPERATOR_SET_REGISTRY: dict[str, tuple[str, ...]] = {
    "full_arithmetic_v1": tuple(OPERATOR_REGISTRY),
    "add_sub_v1": ("add_numeric", "subtract_numeric"),
    "add_sub_div_v1": ("add_numeric", "subtract_numeric", "divide_numeric"),
    "add_sub_mul_v1": ("add_numeric", "subtract_numeric", "multiply_numeric"),
    "multiply_only_v1": ("multiply_numeric",),
    "divide_only_v1": ("divide_numeric",),
    "add_only_v1": ("add_numeric",),
    "subtract_only_v1": ("subtract_numeric",),
    "none_v1": (),
}


def operator_set_manifest() -> dict[str, dict[str, Any]]:
    """Return a serializable registry manifest for result and artifact metadata."""
    return {
        set_id: {
            "operator_set_id": set_id,
            "registry_version": OPERATOR_REGISTRY_VERSION,
            "semantics_version": OPERATOR_SEMANTICS_VERSION,
            "operators": list(operators),
        }
        for set_id, operators in OPERATOR_SET_REGISTRY.items()
    }

Expression = tuple[Any, ...]


def validate_operator_set(operator_set_id: str) -> tuple[str, ...]:
    try:
        return OPERATOR_SET_REGISTRY[operator_set_id]
    except KeyError as exc:
        raise ValueError(f"Unknown operator set: {operator_set_id}") from exc


def raw_expression(column: str) -> Expression:
    return ("raw", str(column))


def op_expression(operator: str, left: Expression, right: Expression) -> Expression:
    if operator not in OPERATOR_REGISTRY:
        raise ValueError(f"Unsupported arithmetic operator: {operator}")
    return ("op", operator, left, right)


def expression_depth(expression: Expression) -> int:
    if expression[0] == "raw":
        return 0
    return 1 + max(expression_depth(expression[2]), expression_depth(expression[3]))


def expression_operators(expression: Expression) -> tuple[str, ...]:
    if expression[0] == "raw":
        return ()
    return (str(expression[1]),) + expression_operators(expression[2]) + expression_operators(expression[3])


def expression_columns(expression: Expression) -> tuple[str, ...]:
    if expression[0] == "raw":
        return (str(expression[1]),)
    return expression_columns(expression[2]) + expression_columns(expression[3])


def expression_to_string(expression: Expression) -> str:
    if expression[0] == "raw":
        return f"[{expression[1]}]"
    spec = OPERATOR_REGISTRY[expression[1]]
    return f"({expression_to_string(expression[2])}{spec.symbol}{expression_to_string(expression[3])})"


def expression_to_dict(expression: Expression) -> dict[str, Any]:
    if expression[0] == "raw":
        return {"kind": "raw", "column": str(expression[1])}
    return {
        "kind": "operation",
        "operator": str(expression[1]),
        "left": expression_to_dict(expression[2]),
        "right": expression_to_dict(expression[3]),
    }


def expression_from_dict(value: dict[str, Any]) -> Expression:
    if value.get("kind") == "raw":
        return raw_expression(str(value["column"]))
    if value.get("kind") == "operation":
        return op_expression(
            str(value["operator"]),
            expression_from_dict(value["left"]),
            expression_from_dict(value["right"]),
        )
    raise ValueError(f"Invalid expression mapping: {value!r}")


def candidate_id(expression: Expression) -> str:
    payload = {
        "registry_version": OPERATOR_REGISTRY_VERSION,
        "semantics_version": OPERATOR_SEMANTICS_VERSION,
        "expression": expression_to_dict(expression),
    }
    encoded = json.dumps(payload, sort_keys=True, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
    return "cand_" + hashlib.sha256(encoded).hexdigest()[:20]


def _finite_output(values: np.ndarray) -> tuple[np.ndarray, dict[str, int]]:
    values = np.asarray(values, dtype=float)
    finite = np.isfinite(values)
    clipped = np.clip(np.where(finite, values, 0.0), -FINITE_CLIP, FINITE_CLIP)
    clipped_count = int(np.count_nonzero(finite & (values != clipped)))
    nonfinite_count = int(np.count_nonzero(~finite))
    return clipped, {"nonfinite_count": nonfinite_count, "clipped_count": clipped_count}


def evaluate_operator(operator: str, left: np.ndarray, right: np.ndarray) -> tuple[np.ndarray, dict[str, int]]:
    """Evaluate one registered operation with the production safety policy."""
    if operator == "add_numeric":
        raw = left + right
    elif operator == "subtract_numeric":
        raw = left - right
    elif operator == "multiply_numeric":
        raw = left * right
    elif operator == "divide_numeric":
        safe = np.abs(right) >= SAFE_DIVISION_EPSILON
        raw = np.zeros_like(left, dtype=float)
        np.divide(left, right, out=raw, where=safe)
        raw[~safe] = 0.0
    else:
        raise ValueError(f"Unsupported arithmetic operator: {operator}")
    output, counts = _finite_output(raw)
    counts["protected_count"] = int(np.count_nonzero(np.abs(right) < SAFE_DIVISION_EPSILON)) if operator == "divide_numeric" else 0
    return output, counts

scientific_definitions.src/seeding.py:
"""Stable, purpose-separated random seeds for benchmark tasks."""

from __future__ import annotations

import hashlib
import json
import math
from collections.abc import Mapping
from typing import Any


SEED_SCHEME_VERSION = "sha256_canonical_json_u32_v1"
SEED_MAX = (1 << 32) - 1


def _canonical_value(value: Any) -> Any:
    """Convert supported task identity values to deterministic JSON values."""
    if value is None or isinstance(value, (str, bool, int)):
        return value
    if isinstance(value, float):
        if not math.isfinite(value):
            raise ValueError("Seed identities cannot contain non-finite floats")
        return value
    if isinstance(value, Mapping):
        if any(not isinstance(key, str) for key in value):
            raise TypeError("Seed identity mapping keys must be strings")
        return {key: _canonical_value(value[key]) for key in sorted(value)}
    if isinstance(value, (tuple, list)):
        return [_canonical_value(item) for item in value]
    raise TypeError(f"Unsupported seed identity value: {type(value).__name__}")


def stable_seed(purpose: str, identity: Mapping[str, Any]) -> int:
    """Derive a uint32 seed from a versioned canonical JSON identity.

    Encoding: UTF-8 JSON with sorted object keys, compact separators, and
    non-ASCII text preserved. The seed is the unsigned big-endian integer from
    the first four bytes of SHA-256 over that encoding. It is in
    ``[0, 2**32 - 1]``, the range accepted by NumPy and scikit-learn.
    """
    if not purpose:
        raise ValueError("A randomness purpose is required")
    payload = {
        "seed_scheme_version": SEED_SCHEME_VERSION,
        "purpose": purpose,
        "identity": _canonical_value(identity),
    }
    encoded = json.dumps(
        payload,
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=False,
        allow_nan=False,
    ).encode("utf-8")
    return int.from_bytes(hashlib.sha256(encoded).digest()[:4], byteorder="big", signed=False)


def _task_identity(
    dataset: str,
    split_policy: str,
    repetition_seed: int,
    *,
    fold: int | None = None,
    condition: str | None = None,
    pipeline: str | None = None,
    model: str | None = None,
    extra: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    identity: dict[str, Any] = {
        "dataset": dataset,
        "split_policy": split_policy,
        "repetition_seed": int(repetition_seed),
        "fold": fold,
        "condition": condition,
        "pipeline": pipeline,
        "model": model,
    }
    if extra:
        identity.update(extra)
    return identity


def split_seed(dataset: str, split_policy: str, repetition_seed: int, n_splits: int) -> int:
    """Seed a complete fold assignment; shared by every condition/pipeline."""
    return stable_seed(
        "split_assignment",
        _task_identity(
            dataset, split_policy, repetition_seed,
            extra={"n_splits": int(n_splits)},
        ),
    )


def corruption_seed(
    dataset: str,
    split_policy: str,
    repetition_seed: int,
    fold: int,
    condition: str,
) -> int:
    """Seed the shared corruption realization for a fold/condition."""
    return stable_seed(
        "training_corruption",
        _task_identity(
            dataset, split_policy, repetition_seed,
            fold=fold, condition=condition,
        ),
    )


def feature_selection_seed(
    dataset: str,
    split_policy: str,
    repetition_seed: int,
    fold: int,
    condition: str,
    pipeline: str,
) -> int:
    """Seed selector randomness in one pipeline without changing shared corruption."""
    return stable_seed(
        "feature_selection",
        _task_identity(
            dataset, split_policy, repetition_seed,
            fold=fold, condition=condition, pipeline=pipeline,
        ),
    )


def estimator_seed(
    dataset: str,
    split_policy: str,
    repetition_seed: int,
    fold: int,
    condition: str,
    model: str,
) -> int:
    """Seed a model fit, shared across pipelines for paired comparisons."""
    return stable_seed(
        "estimator_fit",
        _task_identity(
            dataset, split_policy, repetition_seed,
            fold=fold, condition=condition, model=model,
        ),
    )


def distance_sample_seed(
    dataset: str,
    split_policy: str,
    repetition_seed: int,
    fold: int,
    condition: str,
) -> int:
    """Seed paired row subsampling for held-out distribution diagnostics."""
    return stable_seed(
        "distribution_distance_sample",
        _task_identity(
            dataset, split_policy, repetition_seed,
            fold=fold, condition=condition,
        ),
    )

scientific_definitions.src/splitters.py:
"""Fold construction with explicit target and evaluation boundaries.

Stratified folds use ``y`` only to balance class counts. Covariate and
population folds use the complete predictor matrix ``X`` to define an
unsupervised, dataset-wide geometry before assigning folds. That transductive
use of predictor values is part of these stress-test definitions; labels never
enter their PCA or clustering geometry. These conditions are not estimates of
deployment performance on an unseen population.
"""

from __future__ import annotations

from collections.abc import Sequence

import numpy as np
import pandas as pd
from sklearn.cluster import KMeans
from sklearn.decomposition import PCA
from sklearn.model_selection import KFold, StratifiedKFold
from sklearn.preprocessing import StandardScaler


class SplitInfeasibleError(ValueError):
    """Raised when the requested split policy cannot be satisfied as stated."""


def _validate_split_dimensions(n_rows: int, n_splits: int) -> None:
    if n_splits < 2:
        raise SplitInfeasibleError("n_splits must be at least 2")
    if n_rows < n_splits:
        raise SplitInfeasibleError(
            f"Cannot create {n_splits} folds from {n_rows} rows"
        )


def assert_fold_integrity(
    splits: Sequence[tuple[Sequence[int], Sequence[int]]],
    n_rows: int,
    groups: Sequence[object] | None = None,
) -> None:
    """Validate row coverage, train/test disjointness, and optional group isolation."""
    if not splits:
        raise SplitInfeasibleError("The split policy produced no folds")
    _validate_split_dimensions(n_rows, len(splits))

    row_ids = np.arange(n_rows)
    test_parts: list[np.ndarray] = []
    group_values = None if groups is None else np.asarray(groups, dtype=object)
    if group_values is not None and len(group_values) != n_rows:
        raise SplitInfeasibleError("groups length does not match the number of rows")

    for fold_number, (train_indices, test_indices) in enumerate(splits, start=1):
        train = np.asarray(train_indices, dtype=int)
        test = np.asarray(test_indices, dtype=int)
        if train.ndim != 1 or test.ndim != 1:
            raise SplitInfeasibleError(f"Fold {fold_number} indices must be one-dimensional")
        if train.size == 0 or test.size == 0:
            raise SplitInfeasibleError(f"Fold {fold_number} has an empty train or test partition")
        if np.unique(train).size != train.size or np.unique(test).size != test.size:
            raise SplitInfeasibleError(f"Fold {fold_number} contains duplicate row indices")
        if np.any(train < 0) or np.any(test < 0) or np.any(train >= n_rows) or np.any(test >= n_rows):
            raise SplitInfeasibleError(f"Fold {fold_number} contains an out-of-range row index")
        if np.intersect1d(train, test).size:
            raise SplitInfeasibleError(f"Fold {fold_number} has overlapping train and test rows")
        if np.union1d(train, test).size != n_rows:
            raise SplitInfeasibleError(f"Fold {fold_number} does not partition all rows")
        if group_values is not None:
            train_groups = set(group_values[train].tolist())
            test_groups = set(group_values[test].tolist())
            if train_groups.intersection(test_groups):
                raise SplitInfeasibleError(
                    f"Fold {fold_number} places the same group in train and test"
                )
        test_parts.append(test)

    all_test = np.concatenate(test_parts)
    if np.unique(all_test).size != n_rows or not np.array_equal(np.sort(all_test), row_ids):
        raise SplitInfeasibleError("Test folds must cover every row exactly once")


def get_stratified_splits(
    X: pd.DataFrame,
    y: pd.Series,
    n_splits: int,
    seed: int,
) -> list[tuple[np.ndarray, np.ndarray]]:
    """Create shuffled stratified folds, failing explicitly if class counts are too small."""
    _validate_split_dimensions(len(X), n_splits)
    if len(y) != len(X):
        raise SplitInfeasibleError("X and y lengths differ")
    counts = pd.Series(y).value_counts(dropna=False)
    if counts.empty or int(counts.min()) < n_splits:
        smallest = int(counts.min()) if not counts.empty else 0
        raise SplitInfeasibleError(
            f"Stratified {n_splits}-fold CV requires at least {n_splits} rows per class; "
            f"the smallest class has {smallest}. No random-fold fallback was applied."
        )

    splitter = StratifiedKFold(n_splits=n_splits, shuffle=True, random_state=seed)
    splits = list(splitter.split(X, y))
    assert_fold_integrity(splits, len(X))
    return splits


def _scaled_numeric_predictors(X: pd.DataFrame) -> np.ndarray:
    """Return numeric predictor geometry, rejecting nonnumeric-only inputs."""
    numeric = X.select_dtypes(include=["number"]).fillna(0)
    if numeric.shape[1] == 0:
        raise SplitInfeasibleError(
            "Feature-based partitioning requires at least one numeric predictor; "
            "no alternate random split was substituted."
        )
    return StandardScaler().fit_transform(numeric)


def get_covariate_splits(
    X: pd.DataFrame,
    n_splits: int,
    seed: int,
) -> list[tuple[np.ndarray, np.ndarray]]:
    """Partition by contiguous bins of the first PC of predictor-only geometry.

    PCA and scaling use all rows of ``X`` to define this stress-test partition.
    The function accepts no target argument, so labels cannot affect its folds.
    """
    _validate_split_dimensions(len(X), n_splits)
    scaled = _scaled_numeric_predictors(X)
    pc1 = PCA(n_components=1, random_state=seed).fit_transform(scaled).ravel()
    sorted_indices = np.argsort(pc1, kind="mergesort")
    bins = np.array_split(sorted_indices, n_splits)
    splits = [
        (
            np.concatenate([bins[j] for j in range(n_splits) if j != fold]),
            bins[fold],
        )
        for fold in range(n_splits)
    ]
    assert_fold_integrity(splits, len(X))
    return splits


def get_population_splits(
    X: pd.DataFrame,
    n_splits: int,
    seed: int,
) -> list[tuple[np.ndarray, np.ndarray]]:
    """Hold out one predictor-only K-means cluster per fold.

    Clustering uses all rows of ``X`` to define this unsupervised stress-test
    partition. Empty clusters are an explicit infeasibility; no random K-fold
    replacement is allowed.
    """
    _validate_split_dimensions(len(X), n_splits)
    scaled = _scaled_numeric_predictors(X)
    labels = KMeans(n_clusters=n_splits, random_state=seed, n_init="auto").fit_predict(scaled)
    cluster_sizes = np.bincount(labels, minlength=n_splits)
    if np.any(cluster_sizes == 0):
        raise SplitInfeasibleError(
            f"K-means produced an empty cluster for {n_splits} population folds"
        )

    row_ids = np.arange(len(X))
    splits = [
        (row_ids[labels != cluster], row_ids[labels == cluster])
        for cluster in range(n_splits)
    ]
    assert_fold_integrity(splits, len(X))
    return splits


def get_splits(
    X: pd.DataFrame,
    y: pd.Series,
    split_policy: str,
    n_splits: int,
    seed: int,
) -> list[tuple[np.ndarray, np.ndarray]]:
    """Dispatch an explicit split policy using target labels only for stratification."""
    if split_policy == "stratified":
        return get_stratified_splits(X, y, n_splits, seed)
    if split_policy == "covariate_shift":
        return get_covariate_splits(X, n_splits, seed)
    if split_policy == "population_shift":
        return get_population_splits(X, n_splits, seed)
    raise ValueError(f"Unknown split policy: {split_policy}")
